/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void can_abd_irq_service (void)
{
  if (can_abd.io_base [CANICR] & (0x01 << 7))	//Check if CAN bus is in error
    {
      os_evt_signal_i (can_abd.evt , CAN_IRQ_ABD_RX_BUS_ERROR) ;
  	}
  
  else if (can_abd.io_base [CANICR] & (0x01 << 0))	//Check if CAN msg is received
    {		
      can_abd.io_base [CANCMR] = (0x01 << 2) ; // Release CAN RX buffer
	  os_evt_signal_i (can_abd.evt , CAN_IRQ_ABD_RX_OK) ; 
    }
}



